+`<div class="row" style="margin:0 0 8px"><div style="flex:1;border-top:1px solid var(--bd)"></div><span class="mu">Sort by:</span><span class="mnw"><button class="lnk" data-mn="sort" style="color:var(--tx);font-weight:600">${D.sort=='top'?'Top':'Recent'} ▾</button>${MENU=='sort'?`<div class="mnu" style="left:auto;right:0;min-width:140px"><button data-so="top">Top</button><button data-so="recent">Recent</button></div>`:''}</span></div>`
