function skillT(){D.qa=D.qa||{};D.qr=D.qr||{};return `<div class="card"><b style="font-size:18px">🏅 Skill assessments</b><div class="mu">Answer 4 questions per skill. Score 3 or more to pass and earn a badge (demo).</div></div>`+QZ.map((z,t)=>{const r=D.qr[t],a=D.qa[t]||[];return `<div class="card"><div class="row"><b style="flex:1">${z[0]}</b>${r!=null?`<span class="pill">${r>=3?'🏅 Passed':'Not passed'} · ${r}/${z[1].length}</span>`:''}</div>`+(r!=null?`<div class="mu" style="margin:6px 0 10px">${r>=3?'Badge earned. Nice work!':'You need 3 of 4 to pass. Try again.'}</div><button class="btn" data-qt="${t}">Retake</button>`:z[1].map((q,i)=>`<div style="margin-top:10px"><b>${i+1}. ${esc(q[0])}</b>${q[1].map((o,j)=>`<button class="btn ${a[i]===j?'fill':''}" style="display:block;width:100%;text-align:left;margin-top:6px;border-radius:8px" data-qa="${t}:${i}:${j}">${esc(o)}</button>`).join('')}</div>`).join('')+`<button class="btn fill" style="margin-top:12px" data-qs="${t}" ${z[1].every((q,i)=>a[i]!=null)?'':'disabled'}>Submit</button>`)+'</div>'}).join('')}
function resumeV(){const ex=D.exp.map(x=>Array.isArray(x)?{t:x[0],c:x[1],dt:x[2]}:x),ed=D.edu.map(x=>Array.isArray(x)?{s:x[0],deg:x[1],dt:x[2]}:x),H=t=>`<div style="font-weight:700;color:var(--pr);border-bottom:1px solid var(--bd);margin:14px 0 6px;padding-bottom:2px">${t}</div>`,no=t=>`<div class="mu">${t}</div>`;
return `<div class="card noprint"><b style="font-size:18px">📄 Resume Builder</b><div class="mu">Built from your profile. Add experience, education and skills on your profile to fill it in.</div><div class="pills"><button class="btn fill" data-rpr>🖨 Print / Save as PDF</button><button class="btn" data-rcp>📋 Copy as text</button></div></div><div class="card" id="rs" style="padding:24px"><h2>${esc(U.name)}</h2><div class="mu">${esc(D.headline)} · ${esc(D.loc)}</div><div class="mu">${esc(U.email)}</div>${D.about?H('Summary')+`<div style="white-space:pre-wrap">${esc(D.about)}</div>`:''}${H('Experience')}${ex.map(x=>`<div><b>${esc(x.t||'')}</b> · ${esc(x.c||'')}<div class="mu">${esc(x.dt||'')}</div></div>`).join('')||no('No experience added yet.')}${H('Education')}${ed.map(x=>`<div><b>${esc(x.s||'')}</b> · ${esc(x.deg||'')}<div class="mu">${esc(x.dt||'')}</div></div>`).join('')||no('No education added yet.')}${H('Skills')}<div>${D.skills.map(esc).join(' · ')||no('No skills added yet.')}</div></div>`}
const PLANS=[['Career','₹1,999/mo','See who viewed your profile, get InMail credits and top applicant insights.'],['Business','₹2,999/mo','Grow your network with advanced search and business insights.'],['Sales Navigator','₹6,499/mo','Lead recommendations and real-time sales alerts.'],['Recruiter Lite','₹9,999/mo','Find and reach candidates with smart filters.']];
function prem(){return `<div class="card"><b style="font-size:18px">⭐ LinkSphere Premium</b><div class="mu">Demo plans: no payment is taken. Pick one to try it.</div></div><div class="grid">${PLANS.map(p=>`<div class="card"><b>${p[0]}</b><div style="color:#915907;font-weight:700;margin:4px 0">${p[1]}</div><div class="mu" style="margin-bottom:10px">${p[2]}</div><button class="btn ${D.premP==p[0]?'':'fill'}" data-ptry="${p[0]}">${D.premP==p[0]?'✓ Active · Cancel':'Try free for 1 month'}</button></div>`).join('')}</div>`}
