function viewers(){const t=['2h ago','5h ago','1d ago','1d ago','2d ago','3d ago'];return `<div class="card"><b>Who viewed your profile</b><div class="mu">6 viewers in the past 90 days</div>`+PEOPLE.slice(0,6).map((p,i)=>`<div class="item row">${av(p[0],i+1)}<div style="flex:1">${nm(p[0])}<div class="mu">${p[1]} · ${t[i]}</div></div>${cnBtn(p[0])}</div>`).join('')+'</div>'}
function imp(){const m=mine();return `<div class="card"><b>Post impressions</b><div class="mu">Past 7 days</div><div class="row" style="margin-top:10px;gap:24px"><div><b style="font-size:24px">${imps()}</b><div class="mu">Impressions</div></div><div><b style="font-size:24px">${m.reduce((a,p)=>a+p.l,0)}</b><div class="mu">Reactions</div></div><div><b style="font-size:24px">${m.reduce((a,p)=>a+p.c.length,0)}</b><div class="mu">Comments</div></div></div></div><div class="card"><b>Your posts</b>`+(m.map(p=>`<div class="item"><div>${tag(p.t)}</div><div class="mu">${p.liked?R[p.liked-1][0]:'👍'} ${p.l} · 💬 ${p.c.length} · ${p.l*12+p.c.length*8} impressions</div></div>`).join('')||'<div class="mu">Create a post to see how it performs.</div>')+'</div>'}
